#include <stdio.h>
#include <string.h>
#include <stdbool.h>

#define MAXLEN 64

static bool wildcard_match(const char *pat, const char *txt)
{
    size_t p_len = strlen(pat);
    size_t t_len = strlen(txt);
    bool dp[MAXLEN + 1][MAXLEN + 1] = { { false } };
    dp[0][0] = true;
    for (size_t i = 1; i <= p_len; ++i) {
        char pc = pat[i-1];
        if (pc == '*')
            dp[i][0] = dp[i-1][0];
        else
            dp[i][0] = false;
        for (size_t j = 1; j <= t_len; ++j) {
            char tc = txt[j-1];
            if (pc == '*')
                dp[i][j] = dp[i-1][j] || dp[i][j-1];
            else if (pc == '?')
                dp[i][j] = dp[i-1][j-1];
            else
                dp[i][j] = (pc == tc) && dp[i-1][j-1];
        }
    }
    return dp[p_len][t_len];
}

int main(int argc, char *argv[])
{
    if (argc != 3) {
        puts("USAGE");
        return 0;
    }
    const char *pattern = argv[1];
    const char *text = argv[2];
    if (strlen(pattern) > MAXLEN || strlen(text) > MAXLEN) {
        puts("USAGE");
        return 0;
    }
    if (wildcard_match(pattern, text))
        puts("MATCH");
    else
        puts("NO_MATCH");
    return 0;
}
